    constructor(C _c) { c = _c; }
    function test(address caller, bytes32 identifier, uint256 time, bytes memory ancillaryData) public returns (bool) {
        bool reverted;
        // Capture the initial assertion: only the optimistic asserter succeeds
        // We cannot directly check msg.sender == address(c.optimisticAsserter()), so we compare the revert outcome
        // when called by a non-asserter.
        require(caller != address(c.optimisticAsserter()), "caller must not be the asserter to test restriction");
        // Try to call requestPrice as the non-asserter caller
        (bool s, ) = address(c).call(abi.encodeWithSignature("requestPrice(bytes32,uint256,bytes)", identifier, time, ancillaryData));
        return s;
    }
}

